input.newString:
req, err := http.NewRequestWithContext(ctx, method, u.String(), reqBody)
if err != nil {
	return fmt.Errorf("build request: %w", err)
}

// http.NewRequestWithContext only wires GetBody for the in-memory
// reader types it recognizes. Without GetBody the retry transport
// cannot replay the body and skips retries entirely, so upload
// requests fail immediately on 429. Seekable bodies (for example
// files opened with os.Open) can be rewound, making them safe to
// retry.
if req.GetBody == nil {
	if rs, ok := reqBody.(io.ReadSeeker); ok {
		start, err := rs.Seek(0, io.SeekCurrent)
		if err == nil {
			req.GetBody = func() (io.ReadCloser, error) {
				if _, err := rs.Seek(start, io.SeekStart); err != nil {
					return nil, fmt.Errorf("rewind request body: %w", err)
				}
				return io.NopCloser(rs), nil
			}
		}
	}
}

