func TestFilesService_Upload(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}

		mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		if mediaType != "multipart/form-data" {
			t.Fatalf("unexpected content type: %q", mediaType)
		}

		part, err := multipart.NewReader(r.Body, params["boundary"]).NextPart()
		if err != nil {
			t.Fatalf("read multipart: %v", err)
		}
		if part.FormName() != "file" {
			t.Fatalf("unexpected form name: %q", part.FormName())
		}
		if part.FileName() != "report.pdf" {
			t.Fatalf("unexpected file name: %q", part.FileName())
		}
		content, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if string(content) != "file-payload" {
			t.Fatalf("unexpected file content: %q", string(content))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	file, err := client.Files.Upload(context.Background(), "report.pdf", strings.NewReader("file-payload"))
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 || file.Name != "report.pdf" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Upload_FromOpenFile(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
		if err != nil {
			t.Fatalf("parse content type: %v", err)
		}
		if mediaType != "multipart/form-data" {
			t.Fatalf("unexpected content type: %q", mediaType)
		}

		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart form: %v", err)
		}
		file, header, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		defer file.Close()
		if header.Filename != "report.pdf" {
			t.Fatalf("unexpected file name: %q", header.Filename)
		}
		content, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if string(content) != "file-payload" {
			t.Fatalf("unexpected file content: %q", string(content))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	src, err := os.CreateTemp(t.TempDir(), "upload-*")
	if err != nil {
		t.Fatalf("create temp file: %v", err)
	}
	defer src.Close()
	if _, err := src.WriteString("file-payload"); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	if _, err := src.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("rewind temp file: %v", err)
	}

	file, err := client.Files.Upload(context.Background(), "report.pdf", src)
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Upload_RetriesOn429(t *testing.T) {
	t.Parallel()

	var calls int
	var contents []string
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{MaxAttempts: 3},
	}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart form: %v", err)
		}
		file, _, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		defer file.Close()
		content, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		contents = append(contents, string(content))

		if calls == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"report.pdf"}}`))
	})

	file, err := client.Files.Upload(context.Background(), "report.pdf", strings.NewReader("file-payload"))
	if err != nil {
		t.Fatalf("Upload error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
	for i, content := range contents {
		if content != "file-payload" {
			t.Fatalf("attempt %d sent content %q, want %q", i+1, content, "file-payload")
		}
	}
}

func TestFilesService_Upload_Validation(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
	})

	if _, err := client.Files.Upload(context.Background(), "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, err := client.Files.Upload(context.Background(), "report.pdf", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

